# -*- coding: utf-8 -*-
# patch_exchange_skeleton.py
# ============================================================
# ПАТЧ: каркас Биржи (страница Совета по образцу воркшопа).
# Спринт 45 · 2026-06-16 · ТОЛЬКО СКЕЛЕТ
#
#   1. studio/economy/ui_exchange.py  — НОВЫЙ каркас (копия раскладки
#      воркшопа, наполнен трейдерами A01-A09). Логики Совета пока нет.
#   2. main.py            — импорт page_exchange + маршрут /exchange
#   3. studio/economy/ui_dashboard.py — 4-я кнопка "Биржа" → /exchange
#
# Бэкап (.bak) каждого существующего файла. Запуск из корня репо:
#     python patch_exchange_skeleton.py
# ============================================================
import base64, os, shutil

FILES = {
    "studio/economy/ui_exchange.py": "",
    "main.py": "",
    "studio/economy/ui_dashboard.py": ""
}

def main():
    root = os.getcwd()
    print("=" * 60)
    print("  ПАТЧ: КАРКАС БИРЖИ (скелет Совета)")
    print("  Корень:", root)
    print("=" * 60)
    for dest, b64 in FILES.items():
        path = os.path.join(root, dest.replace("/", os.sep))
        os.makedirs(os.path.dirname(path), exist_ok=True)
        if os.path.exists(path):
            shutil.copy2(path, path + ".bak")
            print(f"  [BAK] {dest} -> {dest}.bak")
        open(path, "wb").write(base64.b64decode(b64))
        print(f"  [OK ] {dest}")
    print("=" * 60)
    print("  ГОТОВО. Запусти студию, открой /dashboard,")
    print("  в правом верхнем углу нажми кнопку 'Биржа' —")
    print("  откроется каркас Совета по образцу воркшопа.")
    print("")
    print("  Это СКЕЛЕТ: пузырьки A01-A09, загрузчик слева,")
    print("  чат+отчёты в центре, аватар справа. Живой Совет")
    print("  подключим следующими шагами.")
    print("=" * 60)

if __name__ == "__main__":
    main()
